import{j as o,Z as l,b as t,c as r,ae as a,A as s,s as d,f as c,q as n,au as E}from"./chunks/framework.D4tMElAP.js";const b=JSON.parse('{"title":"cloudwu/coroutine 与 sylar 协程实现对比","description":"从栈模型、调度模型、IO 能力、内存占用和适用场景对比两个协程实现。","frontmatter":{"title":"cloudwu/coroutine 与 sylar 协程实现对比","description":"从栈模型、调度模型、IO 能力、内存占用和适用场景对比两个协程实现。","date":"2026-06-11T00:00:00.000Z","tags":["coroutine","源码对比"],"categories":["源码分析"]},"headers":[],"relativePath":"research/coroutine/compare.md","filePath":"research/coroutine/compare.md","lastUpdated":1782116278000}'),h={name:"research/coroutine/compare.md"};function u(p,e,A,B,k,D){const i=l("Mermaid");return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[e[1]||(e[1]=a('<h1 id="cloudwu-coroutine-与-sylar-协程实现对比" tabindex="-1">cloudwu/coroutine 与 sylar 协程实现对比 <a class="header-anchor" href="#cloudwu-coroutine-与-sylar-协程实现对比" aria-label="Permalink to “cloudwu/coroutine 与 sylar 协程实现对比”">​</a></h1><p><code>cloudwu/coroutine</code> 和 <code>sylar</code> 都基于 <code>ucontext</code> 完成用户态上下文切换，但它们面向的目标完全不同：前者是极简协程库，后者是服务器框架中的协程运行时。</p><h2 id="核心差异" tabindex="-1">核心差异 <a class="header-anchor" href="#核心差异" aria-label="Permalink to “核心差异”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>cloudwu/coroutine</th><th>sylar</th></tr></thead><tbody><tr><td>语言</td><td>C</td><td>C++</td></tr><tr><td>栈模型</td><td>共享栈，yield 时复制有效栈</td><td>独立栈，每个 Fiber 单独分配</td></tr><tr><td>调度模型</td><td>单线程手动 resume/yield</td><td>N-M 调度器，线程池执行协程</td></tr><tr><td>IO 支持</td><td>无</td><td>epoll + Timer + hook</td></tr><tr><td>状态数量</td><td>READY/RUNNING/SUSPEND/DEAD</td><td>INIT/HOLD/EXEC/TERM/READY/EXCEPT</td></tr><tr><td>内存占用</td><td>低，大量协程更省栈内存</td><td>较高，但切换无需复制栈</td></tr><tr><td>复杂度</td><td>极低</td><td>较高</td></tr><tr><td>适用场景</td><td>学习、轻量嵌入</td><td>网络服务器、异步 IO 框架</td></tr></tbody></table><h2 id="共享栈-vs-独立栈" tabindex="-1">共享栈 vs 独立栈 <a class="header-anchor" href="#共享栈-vs-独立栈" aria-label="Permalink to “共享栈 vs 独立栈”">​</a></h2>',5)),(t(),s(E,null,{default:d(()=>[n(i,{id:"mermaid-117",graph:"flowchart%20LR%0A%20%20A%5B%E5%8D%8F%E7%A8%8B%E6%A0%88%E6%A8%A1%E5%9E%8B%5D%20--%3E%20B%5B%E5%85%B1%E4%BA%AB%E6%A0%88%5D%0A%20%20A%20--%3E%20C%5B%E7%8B%AC%E7%AB%8B%E6%A0%88%5D%0A%20%20B%20--%3E%20D%5B%E8%BF%90%E8%A1%8C%E6%97%B6%E5%85%B1%E7%94%A8%E4%B8%80%E5%9D%97%E6%A0%88%5D%0A%20%20B%20--%3E%20E%5Byield%20%E4%BF%9D%E5%AD%98%E6%9C%89%E6%95%88%E6%A0%88%E7%89%87%E6%AE%B5%5D%0A%20%20B%20--%3E%20F%5B%E5%86%85%E5%AD%98%E6%9B%B4%E7%9C%81%E4%BD%86%E6%9C%89%E6%8B%B7%E8%B4%9D%E6%88%90%E6%9C%AC%5D%0A%20%20C%20--%3E%20G%5B%E6%AF%8F%E4%B8%AA%E5%8D%8F%E7%A8%8B%E5%8D%95%E7%8B%AC%E5%88%86%E9%85%8D%E6%A0%88%5D%0A%20%20C%20--%3E%20H%5B%E5%88%87%E6%8D%A2%E6%97%B6%E6%97%A0%E9%9C%80%E5%A4%8D%E5%88%B6%E6%A0%88%5D%0A%20%20C%20--%3E%20I%5B%E5%86%85%E5%AD%98%E5%8D%A0%E7%94%A8%E6%9B%B4%E9%AB%98%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p><code>cloudwu/coroutine</code> 的共享栈方案更像一个精巧的底层机制：它证明了协程不一定需要为每个实例保留完整栈空间。</p><p><code>sylar</code> 的独立栈方案更接近工程运行时：切换路径更直接，也更容易与调度器、IO 等模块组合。</p><h2 id="调度能力对比" tabindex="-1">调度能力对比 <a class="header-anchor" href="#调度能力对比" aria-label="Permalink to “调度能力对比”">​</a></h2><p><code>cloudwu/coroutine</code> 的调度由使用者显式控制：</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coroutine_resume</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(S, id);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coroutine_yield</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(S);</span></span></code></pre></div><p>它不关心任务队列，也不关心 IO 事件，只负责在主上下文和协程上下文之间切换。</p><p><code>sylar</code> 的调度器则负责：</p><ul><li>接收协程和函数任务。</li><li>在线程池中分发任务。</li><li>根据协程状态决定是否重新入队。</li><li>无任务时进入 idle 协程。</li><li>与 IOManager 配合，在 IO 就绪后恢复协程。</li></ul><h2 id="io-能力对比" tabindex="-1">IO 能力对比 <a class="header-anchor" href="#io-能力对比" aria-label="Permalink to “IO 能力对比”">​</a></h2><p><code>cloudwu/coroutine</code> 没有 IO 调度能力。如果协程中调用阻塞 IO，会阻塞整个线程。</p><p><code>sylar</code> 通过 <code>IOManager</code> 解决这个问题：</p><ul><li>fd 事件注册到 epoll。</li><li>当前协程 yield。</li><li>epoll 事件到达后，<code>FdContext::triggerEvent</code> 将协程重新 schedule。</li><li>hook 层把阻塞系统调用改造成协程挂起。</li></ul><p>因此 sylar 可以支撑高并发网络服务。</p><h2 id="如何选择" tabindex="-1">如何选择 <a class="header-anchor" href="#如何选择" aria-label="Permalink to “如何选择”">​</a></h2><p>适合选择 <code>cloudwu/coroutine</code> 的情况：</p><ul><li>想学习协程最小实现。</li><li>需要一个极轻量、可嵌入的 C 协程库。</li><li>协程数量多，但单个协程挂起时栈占用较小。</li></ul><p>适合参考 <code>sylar</code> 的情况：</p><ul><li>想实现网络服务器运行时。</li><li>需要多线程协程调度。</li><li>需要 IO 事件、定时器、hook 等工程能力。</li><li>希望业务层用同步写法编写异步 IO 逻辑。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p><code>cloudwu/coroutine</code> 适合理解“协程为什么能切换”和“共享栈如何保存恢复”。</p><p><code>sylar</code> 适合理解“协程如何成为服务器框架运行时”，重点在调度器、IOManager、hook 与 Fiber 的组合。</p>`,21))])}const m=o(h,[["render",u]]);export{b as __pageData,m as default};
